cat = json.load(open(KAT)); s = cat['strings']; n = 0
index = {}
for key in s: index.setdefault(PH.sub('§', key), []).append(key)
for k, (en, es, fr) in U.items():
    keys = index.get(PH.sub('§', k)) or []
    if not keys:
        if en is None: continue
        s[k] = {"localizations": {}}; keys = [k]
    for key in keys:
        loc = s[key].setdefault('localizations', {})
        for sp, v in (('en', en), ('es', es), ('fr', fr)):
            if v is not None and sp not in loc: loc[sp] = {"stringUnit": {"state": "translated", "value": v}}; n += 1
orig = open(KAT).read()
open(KAT, 'w').write(json.dumps(cat, ensure_ascii=False, indent=2, separators=(',', ': ')) + ('\n' if orig.endswith('\n') else ''))
print('eingetragen:', n)
